def info(title,desc,icon='✦'):
    return f'<article class="info"><span class="infoicon">{icon}</span><h3>{title}</h3><p>{desc}</p></article>'
def details(title,copy):return f'<details><summary>{title}</summary><p>{copy}</p></details>'
def searchgrid(gs):return '<div class="searchwrap"><label for="zoek">Vind je volgende demo</label><input id="zoek" class="search" type="search" placeholder="Zoek op spelnaam…"><p class="searchstatus" role="status"></p></div><div class="grid catalog">'+tiles(gs)+'</div><p class="empty" hidden>Geen spellen gevonden. Probeer een andere naam.</p>'
