page('toernooien.html','Toernooien',heading('Jouw plek in het fictieve klassement','Speel mee voor de sfeer','Meld je lokaal aan voor een demo-toernooi. De voorbeeldranglijst en virtuele prijzen zijn illustratief, niet gekoppeld aan andere spelers.','🏆','#9a6523')+'<main><div class="tournaments">'+''.join(f'<article class="tourney info"><span class="pill">DEMO-EVENEMENT</span><h2>{n}</h2><p>Uitgelicht: {game}</p><strong>{prize:,} virtuele credits</strong><p>Nieuwe voorbeeldronde over <b data-countdown="{sec}">—</b></p><button class="btn" data-join="{key}">Deelnemen (demo)</button><a class="lnk" href="spel/{slug}.html">Naar het spel →</a><p class="joined" aria-live="polite"></p></article>' for key,n,game,slug,prize,sec in TOURS)+'</div><section class="rules"><h2>Voorbeeldranglijst</h2><p>Fictieve namen en scores ter illustratie. Geen live competitie.</p><table><thead><tr><th>Plaats</th><th>Speler</th><th>Voorbeeldpunten</th></tr></thead><tbody><tr><td>1</td><td>Duinlicht</td><td>840</td></tr><tr><td>2</td><td>Mosreiziger</td><td>720</td></tr><tr><td>3</td><td>Poolvonk</td><td>610</td></tr></tbody></table></section><div class="featurepair">'+info('Lokaal aanmelden','Je deelname wordt alleen in je browser opgeslagen. Je kunt haar op ieder moment weer intrekken.','✓')+info('Geen echte prijzen','Prijzen en scores zijn voorbeelden; je ontvangt niets buiten de preview.','💠')+'</div></main>')
