page('extras.html','Quinara Extra',heading('Een eigen plekje in de lobby','Jouw Quinara Extra','Ontdek meer, bewaar je favorieten en vink een demo-uitdaging af. Alles blijft lokaal op dit apparaat.','🌟','#5c4b99')+'<main><section class="featurepair"><article class="info"><span class="infoicon">🧭</span><h2>Vandaag: ontdek een nieuwe wereld</h2><p>Probeer een spel dat je nog niet kent. Klaar? Vink het hieronder af. Je ontvangt geen echte prijs.</p><button class="btn" data-join="ontdekken">Uitdaging afvinken</button><p class="joined" aria-live="polite"></p></article>'+info('Een bibliotheek vol eigen ideeën','De Quinara-spellen zijn voor deze preview gebouwd. Er zijn geen externe aanbieders of echte casinoverbindingen.','✦')+'</section><h2>Jouw favorieten</h2><p>Gebruik het hartje op een spelkaart om hem hier te bewaren.</p><div id="favorites" class="grid"></div><a class="btn g" href="spellen.html">Alle spellen ontdekken</a></main>')
faq=[('Kan ik hier echt spelen?','Nee. Dit is een fictief ontwerp met uitsluitend virtuele credits en zonder echte prijzen. Er is geen betaalfunctie.'),('Heb ik een account nodig?','Nee. Proberen werkt direct. Een demo-account is alleen een lokale simulatie en blijft in de browser.'),('Ik ben mijn wachtwoord vergeten','Gebruik het demo-account of open de aparte hulppagina. Er worden geen herstelmails verstuurd.'),('Waar worden mijn gegevens opgeslagen?','In localStorage op dit apparaat. Ze worden niet naar een server gestuurd. Gebruik daarom geen echt wachtwoord of persoonlijke gegevens.'),('Waarom zie ik geen echte dealers?','De hosts zijn illustraties en de tafels zijn eigen browserdemo’s. Er worden geen livestreams getoond.'),('Hoe reset ik credits?','Ga naar Account en klik op Saldo resetten. Je krijgt weer 1.000 virtuele credits.')]
page('klantenservice.html','Klantenservice',heading('We maken het graag duidelijk','Waar kunnen we je mee helpen?','Lees de veelgestelde vragen of test het contactformulier. Het formulier verstuurt niets: je ziet alleen een lokale bevestiging.','💬','#287584')+'<main><section class="faq"><h2>Veelgestelde vragen</h2>'+''.join(details(q,a) for q,a in faq)+'</section><section class="contact info"><div><h2>Test het contactformulier</h2><p>Vul fictieve gegevens in. Geen mail, geen ticket en geen opslag op een server.</p><a class="lnk" href="wachtwoord-vergeten.html">Hulp bij inloggen →</a></div><form id="contact"><div class="fld"><label for="onderwerp">Onderwerp</label><select id="onderwerp"><option>Een spel proberen</option>Mijn demo-account</option>Feedback op het ontwerp</option></select></div><div class="fld"><label for="bericht">Jouw fictieve bericht</label><textarea id="bericht" required minlength="5" placeholder="Testbericht…"></textarea></div><button class="btn">Testformulier afronden</button><p id="contactstatus" role="status"></p></form></section></main>')
page('verantwoord-spelen.html','Verantwoord spelen',heading('Een goed moment om stil te staan','Jij bepaalt je grenzen','Quinara is alleen een preview voor 18+. Ook met virtuele credits kun je oefenen met bewuste keuzes, rust en pauzes.','🌿','#226c4b')+'<main><div class="featuretrio">'+info('18 jaar en ouder','Deze preview is alleen bedoeld voor volwassenen. Deel hem niet als een kansspel voor minderjarigen.','18+')+info('Speel zonder geldwaarde','Credits zijn niet te koop, niet inwisselbaar en niet uitkeerbaar. Winst in een demo zegt niets over echte kansspelen.','💠')+info('Neem pauze','Bepaal vooraf hoelang je wilt spelen. Stop als het niet meer leuk voelt.','⏳')+'</div><section class="info"><h2>Jouw lokale sessievoorkeuren</h2><p>Dit zijn browserherinneringen, geen bindende blokkades of echte zelfuitsluiting.</p><form id="limits"><div class="fld"><label for="minutes">Herinner mij na</label><select id="minutes"><option value="0">Geen herinnering</option><option value="1">1 minuut (test)</option><option value="15">15 minuten</option><option value="30">30 minuten</option><option value="60">60 minuten</option></select></div><button class="btn g">Voorkeur opslaan</button><p id="limitstatus" role="status"></p></form></section><section class="faq"><h2>Bewust en transparant</h2>'+details('Wat doet de herinnering?','Na de ingestelde tijd verschijnt een pauzebericht zolang de pagina open is. De voorkeur blijft lokaal bewaard; je kunt hem altijd wijzigen.')+details('Kunnen demo’s verwachtingen beïnvloeden?','Ja. Een demo is geen voorspelling van winst. Deze spellen hebben vereenvoudigde regels en geen onafhankelijk gecontroleerd uitbetalingspercentage.')+details('Maak je je zorgen over echt gokken?','Praat met iemand die je vertrouwt, je huisarts of een erkende verslavingszorgorganisatie. Een preview zoals deze vervangt geen professionele hulp.')+'</section></main>',sub=False)
page('account.html','Account',heading('Je persoonlijke demohoek','Mijn Quinara','Beheer je lokale demosaldo, favoriete spellen en demo-account. Niets wordt gesynchroniseerd met een server.','👤','#285782')+'<main><div class="featurepair"><section class="info"><h2>Jouw demo-account</h2><div id="accountPanel"></div></section><section class="info"><span class="infoicon">💠</span><h2><span data-cred></span> virtuele credits</h2><p>Geen echt geld of prijzen. Het saldo staat alleen in je browser.</p><button class="btn g" id="resetCredits">Saldo resetten naar 1.000</button><p id="resetstatus" role="status"></p></section></div><div class="featurepair"><a class="info actiontile" href="extras.html"><h2>Jouw favorieten →</h2><p>Ga naar Quinara Extra om opgeslagen spellen te bekijken.</p></a><a class="info actiontile" href="verantwoord-spelen.html"><h2>Jouw speeltempo →</h2><p>Stel een lokale pauzeherinnering in.</p></a></div><section class="rules"><h2>Over lokale opslag</h2><p>Dit account is geen echte gebruikersdienst. Gebruik alleen verzonnen gegevens en een uniek demowachtwoord. Browsergegevens wissen verwijdert je lokale account en voorkeuren.</p><button class="lnk" id="clearDemo">Lokale demo-gegevens wissen</button><p id="clearstatus" role="status"></p></section></main>',sub=False)
page('wachtwoord-vergeten.html','Hulp bij inloggen',f'<main class="auth" style="max-width:none"><section class="acard">{MARK}<h1>Hulp bij je demo-account</h1><p>Deze preview heeft geen mailserver. We versturen geen herstelmail en vragen geen echte persoonsgegevens.</p><div class="rules"><b>Het vaste demo-account</b><p>demo@quinara.test<br>Quinara-Demo-2026</p></div><p>Je eigen lokale account vergeten? Gebruik het vaste demo-account of wis je lokale demo-gegevens op de accountpagina.</p><a class="btn w" href="inloggen.html">Terug naar inloggen</a><p><a class="lnk" href="account.html">Lokale gegevens beheren</a></p></section></main>',auth=True)
# All catalogue titles get a distinct route, honest rules and the shared original engine.
RULES={
'slot':('Vijf rollen · drie winlijnen','Per horizontale rij: 3, 4 of 5 gelijke symbolen vanaf links betalen respectievelijk 1×, 4× of 15× een derde van je inzet. Symbool 4 en 5 betalen dubbel. Het laatste symbool is wild en vervangt andere symbolen. Bedragen worden afgerond op hele credits.'),
'wheel':('Een rondje fortuin','Draai het rad en ontvang je inzet maal de vermenigvuldiger bij de bovenste wijzer. De twaalf gelijke vakken hebben waarden 0, 1,5, 0, 2, 0,5, 0, 3, 0, 1,2, 5, 0 en 1,5. Dit is een eigen demo, geen echt prijzenrad.'),
'drop':('Volg de dauwdruppel','De druppel kiest bij ieder van acht pinrijen willekeurig links of rechts. De vakken van links naar rechts betalen 5×, 2×, 1,2×, 0,5×, 0,3×, 0,5×, 1,2×, 2× en 5×. Middenvakken worden vaker geraakt dan de randen.'),
'higher':('Hoger of lager?','Raad of de volgende kaart hoger of lager is. Van laag naar hoog: 2 t/m 10, boer, vrouw, heer, aas. Goed geeft 1,9× de inzet terug. Gelijk geeft de inzet terug. Elke kaart wordt opnieuw willekeurig getrokken.'),
'rise':('Een kwestie van timing','Start met 1× en betaal de virtuele inzet. Het getal stijgt tot een willekeurig crashpunt. Stop daarvoor om je inzet maal de getoonde factor te ontvangen. Een crash kan direct optreden. Het theoretische model heeft een ingebouwd nadeel voor de speler en is geen winststrategie.'),
'roulette':('Het Quinara kleurenrad','Kies rood, groen of goud. Het rad heeft 12 gelijke vakken: 5 rood, 5 groen en 2 goud. Goed gekozen rood/groen betaalt 2×, goud betaalt 5×. Alle uitbetalingen zijn inclusief de inzet.'),
'blackjack':('Eenentwintig, eenvoudig uitgelegd','Probeer dichter bij 21 te komen dan de demo-host, zonder eroverheen te gaan. Figuren zijn 10, aas is 1 of 11. Neem een kaart of pas. De host trekt tot 17. Winst betaalt 2×, gelijk geeft je inzet terug. Geen splitsen of verdubbelen; dit is een vereenvoudigde eigen variant.'),
'compare':('Twee handen vergelijken','Kies hand Maan of hand Zon. Beide krijgen twee kaarten met waarden 0–9; de som modulo 10 is de score. De hoogste hand wint en betaalt 1,9×. Bij gelijk krijg je je inzet terug. Geen derde kaart: deze eigen variant gebruikt geen officiële casinotafelregels.'),
'poker':('Vijfkaarten Paar','Kies je inzet en trek vijf kaarten uit een geschud spel. Kies kaarten die je wilt behouden en wissel de rest één keer. Hoogste combinatie betaalt: paar 1×, twee paar 2×, drie gelijke 3×, straat 4×, kleur 6×, full house 8×, vier gelijke 20×, straight flush 40×. Geen paar: 0. Uitbetaling is inclusief inzet.'),
'bingo':('Eigen bingo met 25 vakjes','Je kaart bevat 24 unieke getallen van 1–75 en een vrij middenvak. Nummers worden zonder terugleggen getrokken en automatisch gemarkeerd. Na het vaste aantal trekkingen: minstens één volle horizontale rij, verticale kolom of diagonaal betaalt 3× de inzet, anders niets. Je kunt trekkingen handmatig doen of automatisch afspelen.'),
'sport':('Een fictief voorspellingsbriefje','Kies één van twee verzonnen deelnemers. De simulatie kiest met gelijke kans een winnaar. Goed voorspeld: 2× je inzet terug. Mis: geen uitbetaling. Dit zijn geen echte wedstrijden, sportuitslagen of aangeboden weddenschappen.')}
for g in CATALOG:
    en=g['engine'];sub,rules=RULES[en]
    if en=='bingo':rules=rules.replace('1–75','1–'+str(g.get('maxNumber',75)))
    context=f'<p class="hostlabel">{g["icon"]} Demo-host {g["host"]} · illustratie, geen livestream</p>' if g.get('host') else ''
    intro=f'Ontdek {g["name"]}: {sub.lower()}. Speel rechtstreeks met virtuele credits; er zijn geen echte prijzen.'
    body=heading(g['category'],g['name'],intro,g['icon'],g['a'])+f'<main class="game"><a class="backlink" href="../{ {"Live Casino":"live","Bingo":"bingo","Sport":"sport","Slots":"slots","Arcade":"arcade","Tafelspellen":"tafelspellen","Jackpots":"jackpots"}[g["category"]] }.html">← Terug naar {g["category"]}</a>{context}<div class="gbox" style="--game-accent:{g["a"]}"><div class="gamehead"><span>DEMO · GEEN GELDWAARDE</span><strong>💠 <span data-cred></span> credits</strong></div><div id="stage" class="stage" aria-label="Spelveld"></div><div class="ctl"><label for="bet">Virtuele inzet</label><select id="bet"><option value="10">10 credits</option><option value="20">20 credits</option><option value="50">50 credits</option><option value="100">100 credits</option></select><div id="controls"></div></div><p class="msg" id="msg" aria-live="polite">Kies een inzet en probeer een ronde.</p></div><section class="rules"><span class="eyebrow">DE SPELREGELS</span><h2>{sub}</h2><p>{rules}</p><p><b>Dit is een eigen, vereenvoudigde spelengine. Geen echt geld, geen echte prijzen. Resultaten zijn willekeurig en niet onafhankelijk gecertificeerd.</b></p></section><section class="featurepair">'+info('Een pauze mag altijd','Je hoeft niets terug te winnen. Virtuele credits kun je gratis resetten via Account.','🌿')+f'<a class="info actiontile" href="../spellen.html"><h3>Meer ontdekken →</h3><p>Terug naar de volledige spellobby.</p></a></section></main><script>window.GAME={json.dumps(g,ensure_ascii=False)};</script><script src="../games.js"></script>'
    page(f'spel/{g["slug"]}.html',g['name'],body)
open('catalog.json','w').write(json.dumps(CATALOG,ensure_ascii=False))
